typedef long long ll;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char **g = (char **)malloc(N * sizeof(char *));
    for (int i = 0; i < N; i++) {
        g[i] = (char *)malloc((M + 5) * sizeof(char));
        scanf("%s", g[i]);
    }

    /*
      Key idea:
      A move only goes Right or Down, so pieces never interfere "backwards".
      For each connected segment of free cells between obstacles in a row/column,
      pieces can be pushed toward the bottom-right as much as possible.

      Equivalent counting:
      In each obstacle-separated region, the final arrangement is determined by
      preserving relative order under right/down moves, and the maximum total
      number of moves equals:
        sum(final_row - initial_row) + sum(final_col - initial_col)

      This separates into row and column parts:
      - Vertical moves depend only on counts of pieces in each obstacle-separated
        column segment.
      - Horizontal moves depend only on counts of pieces in each obstacle-separated
        row segment.

      For a segment with free positions indexed p[0..L-1] and k pieces initially
      at positions of indices a[0] < ... < a[k-1], the optimal final positions are
      the last k cells of the segment:
         L-k, L-k+1, ..., L-1
      so contribution is:
         sum((L-k+t) - a[t]) for t=0..k-1
    */

    ll ans = 0;

    /* Horizontal contributions */
    for (int i = 0; i < N; i++) {
        int j = 0;
        while (j < M) {
            while (j < M && g[i][j] == '#') j++;
            if (j >= M) break;

            int start = j;
            int len = 0, k = 0;
            int *pos = NULL;
            int cap = 0;

            while (j < M && g[i][j] != '#') {
                if (g[i][j] == 'o') {
                    if (k >= cap) {
                        cap = cap ? cap * 2 : 4;
                        pos = (int *)realloc(pos, cap * sizeof(int));
                    }
                    pos[k++] = len;
                }
                len++;
                j++;
            }

            for (int t = 0; t < k; t++) {
                ans += (ll)(len - k + t - pos[t]);
            }
            free(pos);
            (void)start;
        }
    }

    /* Vertical contributions */
    for (int j = 0; j < M; j++) {
        int i = 0;
        while (i < N) {
            while (i < N && g[i][j] == '#') i++;
            if (i >= N) break;

            int len = 0, k = 0;
            int *pos = NULL;
            int cap = 0;

            while (i < N && g[i][j] != '#') {
                if (g[i][j] == 'o') {
                    if (k >= cap) {
                        cap = cap ? cap * 2 : 4;
                        pos = (int *)realloc(pos, cap * sizeof(int));
                    }
                    pos[k++] = len;
                }
                len++;
                i++;
            }

            for (int t = 0; t < k; t++) {
                ans += (ll)(len - k + t - pos[t]);
            }
            free(pos);
        }
    }

    printf("%lld\n", ans);

    for (int i = 0; i < N; i++) free(g[i]);
    free(g);
    return 0;
}

