int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    vector<string> S(N);
    for (int i = 0; i < N; ++i) cin >> S[i];

    long long ans = 0;

    // Horizontal moves:
    // In each row, within every segment separated by '#',
    // if there are len cells and k pieces, we can maximize moves by placing
    // pieces as far right as possible. Total moves = sum of distances moved
    // = k * len - k*(k+1)/2 - sum(original positions from left, 1-indexed).
    for (int i = 0; i < N; ++i) {
        int j = 0;
        while (j < M) {
            if (S[i][j] == '#') {
                ++j;
                continue;
            }
            int l = j;
            while (j < M && S[i][j] != '#') ++j;
            int r = j; // [l, r)
            long long len = r - l;
            long long k = 0;
            long long sumPos = 0; // 1-indexed within segment
            for (int c = l; c < r; ++c) {
                if (S[i][c] == 'o') {
                    ++k;
                    sumPos += (c - l + 1);
                }
            }
            ans += k * len - k * (k + 1) / 2 - sumPos;
        }
    }

    // Vertical moves:
    // Same logic for each column, within segments separated by '#'.
    for (int j = 0; j < M; ++j) {
        int i = 0;
        while (i < N) {
            if (S[i][j] == '#') {
                ++i;
                continue;
            }
            int l = i;
            while (i < N && S[i][j] != '#') ++i;
            int r = i; // [l, r)
            long long len = r - l;
            long long k = 0;
            long long sumPos = 0; // 1-indexed within segment
            for (int x = l; x < r; ++x) {
                if (S[x][j] == 'o') {
                    ++k;
                    sumPos += (x - l + 1);
                }
            }
            ans += k * len - k * (k + 1) / 2 - sumPos;
        }
    }

    cout << ans << '\n';
    return 0;
}

