import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, rev, cap;
        Edge(int to, int rev, int cap) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
        }
    }

    static class Dinic {
        int n;
        ArrayList<Edge>[] g;
        int[] level, it;

        @SuppressWarnings("unchecked")
        Dinic(int n) {
            this.n = n;
            g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
            level = new int[n];
            it = new int[n];
        }

        void addEdge(int fr, int to, int cap) {
            Edge fwd = new Edge(to, g[to].size(), cap);
            Edge rev = new Edge(fr, g[fr].size(), 0);
            g[fr].add(fwd);
            g[to].add(rev);
        }

        boolean bfs(int s, int t) {
            Arrays.fill(level, -1);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            level[s] = 0;
            q.add(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (Edge e : g[v]) {
                    if (e.cap > 0 && level[e.to] < 0) {
                        level[e.to] = level[v] + 1;
                        q.add(e.to);
                    }
                }
            }
            return level[t] >= 0;
        }

        int dfs(int v, int t, int f) {
            if (v == t) return f;
            for (; it[v] < g[v].size(); it[v]++) {
                Edge e = g[v].get(it[v]);
                if (e.cap > 0 && level[v] + 1 == level[e.to]) {
                    int ret = dfs(e.to, t, Math.min(f, e.cap));
                    if (ret > 0) {
                        e.cap -= ret;
                        g[e.to].get(e.rev).cap += ret;
                        return ret;
                    }
                }
            }
            return 0;
        }

        int maxFlow(int s, int t) {
            int flow = 0;
            int INF = 1 << 30;
            while (bfs(s, t)) {
                Arrays.fill(it, 0);
                int f;
                while ((f = dfs(s, t, INF)) > 0) flow += f;
            }
            return flow;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();
        char[][] board = new char[N][];
        for (int i = 0; i < N; i++) board[i] = fs.next().toCharArray();

        int cells = N * M;
        int S = cells;
        int T = cells + 1;
        Dinic dinic = new Dinic(cells + 2);

        int[] dr = {0, 1};
        int[] dc = {1, 0};

        for (int r = 0; r < N; r++) {
            for (int c = 0; c < M; c++) {
                if (board[r][c] != 'o') continue;
                int id = r * M + c;

                // Bipartite by parity of (r+c)
                if (((r + c) & 1) == 0) {
                    dinic.addEdge(S, id, 1);
                    for (int k = 0; k < 2; k++) {
                        int nr = r + dr[k];
                        int nc = c + dc[k];
                        if (0 <= nr && nr < N && 0 <= nc && nc < M && board[nr][nc] == 'o') {
                            int nid = nr * M + nc;
                            dinic.addEdge(id, nid, 1);
                        }
                    }
                } else {
                    dinic.addEdge(id, T, 1);
                }
            }
        }

        System.out.println(dinic.maxFlow(S, T));
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

